solutionCode:
use std::collections::HashMap;

pub fn apuramento(votos: Vec<String>) -> String {
    let mut contagem = HashMap::new();
    for voto in votos {
        *contagem.entry(voto).or_insert(0) += 1;
    }
    let da_ana = match contagem.get("ana") {
        Some(n) => *n,
        None => 0,
    };
    format!("ana: {} votos", da_ana)
}

testsCode:
use desafio::apuramento;

#[test]
fn testa_a_ana_com_dois_votos() {
    let votos = vec![String::from("ana"), String::from("bo"), String::from("ana")];
    assert_eq!(apuramento(votos), "ana: 2 votos");
}

#[test]
fn testa_a_ana_sem_voto_nenhum() {
    let votos = vec![String::from("bo")];
    assert_eq!(apuramento(votos), "ana: 0 votos");
}

#[test]
fn testa_a_urna_vazia() {
    let votos = vec![];
    assert_eq!(apuramento(votos), "ana: 0 votos");
}
